<template>
  <q-page class="page">
    <section class="top"><div><p class="eyebrow">ADMINISTRAÇÃO</p><h1 class="page-title">Importar questões</h1><p>Envie PDFs para o banco global; concurso, banca e ano são identificados como metadados de origem.</p></div></section>
    <q-banner v-if="error" rounded class="error">{{ error }}</q-banner><q-banner v-if="success" rounded class="success">{{ success }}</q-banner>
    <q-card flat class="card"><q-card-section><div class="section-title"><div><h2>Importar PDFs de questões</h2><p>Os arquivos entram na fila. O worker extrai questões objetivas, identifica origem e classifica na taxonomia.</p></div><q-chip color="blue-1" text-color="primary" icon="schedule">Processamento assíncrono</q-chip></div><div class="upload-grid"><q-file v-model="pdfDocuments" outlined dense multiple accept="application/pdf,.pdf" label="PDFs com questões" use-chips clearable><template #prepend><q-icon name="upload_file"/></template></q-file></div><div class="upload-action"><span>{{ pdfDocuments.length ? pdfDocuments.length + ' arquivo(s) selecionado(s)' : 'Selecione um ou mais PDFs.' }}</span><q-btn unelevated no-caps color="primary" icon="queue" label="Enviar para a fila" :disable="!pdfDocuments.length" :loading="loading" @click="queuePdfBatch"/></div></q-card-section></q-card>
    <q-card v-if="activePdfJobs.length" flat class="card"><q-card-section><div class="section-title"><div><h2>Importações em andamento</h2><p>Atualização automática enquanto houver arquivos na fila.</p></div><q-btn flat dense no-caps icon="refresh" label="Atualizar" @click="refreshPdfJobs"/></div><import-job-list :jobs="activePdfJobs" cancellable @cancel="cancelPdfJob"/></q-card-section></q-card>
    <q-expansion-item v-if="pdfJobTotal || historyLoading" v-model="historyOpen" class="card history" icon="history" :label="'Histórico de importações (' + pdfJobTotal + ')'" caption="Concluídas e com falha ficam aqui para não poluir a fila." @show="loadPdfJobs"><q-card-section><q-inner-loading :showing="historyLoading"/><q-banner v-if="!historyLoading && !finishedPdfJobs.length" rounded class="empty">Nenhuma importação concluída ou com falha foi encontrada.</q-banner><import-job-list v-else :jobs="finishedPdfJobs"/></q-card-section></q-expansion-item>
    <q-expansion-item class="card legacy" icon="data_object" label="Importação estruturada (JSON/CSV)" caption="Valide e crie rascunhos a partir de dados estruturados."><q-card-section class="q-gutter-md"><q-select v-model="format" outlined label="Formato" :options="['JSON','CSV']"/><q-input v-model="content" outlined type="textarea" autogrow label="Conteúdo da importação"/><q-btn unelevated no-caps color="primary" label="Validar importação" :loading="loading" @click="previewImport"/></q-card-section><q-card-section v-if="report"><h2>Relatório de validação</h2><p>{{ report.validRows }} linhas válidas · {{ report.invalidRows }} bloqueadas para revisão</p><q-list bordered separator><q-item v-for="row in report.rows" :key="row.rowNumber"><q-item-section><q-item-label>Linha {{ row.rowNumber }} — {{ row.valid ? 'pronta para rascunho' : 'revisão necessária' }}</q-item-label><q-item-label v-if="row.errors.length" caption>{{ row.errors.map(item => item.message).join(' · ') }}</q-item-label></q-item-section></q-item></q-list><q-btn class="q-mt-md" unelevated no-caps color="primary" label="Confirmar linhas válidas" :disable="!syllabusId || !report.validRows" :loading="loading" @click="commitImport"/></q-card-section></q-expansion-item>
  </q-page>
</template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'
import ImportJobList from './ImportJobList.vue'
import { useImport } from './useImport'
const format = ref<'JSON' | 'CSV'>('JSON'); const content = ref(''); const syllabusId = ref(''); const pdfDocuments = ref<File[]>([]); const historyOpen = ref(false)
const { activePdfJobs, cancelPdfJob, commit, error, finishedPdfJobs, historyLoading, loadExams, loadPdfJobs, loading, pdfJobTotal, preview, queuePdfs, refreshPdfJobs, report, success } = useImport()
async function previewImport() { await preview(format.value, content.value) } async function commitImport() { await commit(syllabusId.value) } async function queuePdfBatch() { await queuePdfs(pdfDocuments.value); pdfDocuments.value = [] }
onMounted(async () => { await Promise.all([loadExams(), loadPdfJobs()]) })
</script>
<style scoped>
.page{max-width:1100px;margin:auto;padding:42px 34px}.top{margin-bottom:20px}.eyebrow{color:#7187ad;font-size:11px;font-weight:800;letter-spacing:.1em}.card{background:#fff;border:1px solid #e5ecf6;border-radius:16px;margin-top:16px}.section-title{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.section-title h2{margin:0;color:#102a5c;font-size:18px}.section-title p{margin:5px 0 0;color:#637797}.upload-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:18px}.upload-action{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-top:16px;color:#637797;font-size:13px}.error{margin-top:16px;background:#fff3f2;color:#ae2f25}.success{margin-top:16px;background:#edf9f1;color:#22764a}.empty{background:#f5f8fd;color:#637797}.history{overflow:hidden}.legacy{padding:4px 12px}@media(max-width:700px){.page{padding:28px 16px}.upload-grid{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}.upload-action,.section-title{align-items:stretch;flex-direction:column}}
</style>
